style.css:
@-moz-document domain("polybuzz.ai"), domain("polybuzz.cc") {
/* 1. Main Dreamy Pink Background & Whimsical Fonts */
    body, html, main, .main-container, #__next, .layout-container {
        background-color: #fff0f3 !important; /* Soft strawberry milk pink */
        background-image: radial-gradient(#ffe3e8 1px, transparent 1px) !important; /* Tiny fairy-dot pattern */
        background-size: 20px 20px !important;
        color: #5c4d5a !important; /* Deep soft plum for readable text, instead of harsh black */
        font-family: 'Segoe UI', 'Quicksand', 'Nunito', sans-serif !important;
    }

    /* 2. Main Chat Window Panel */
    .chat-box, .chat-container, [class*="chat_window"], .message-list-container {
        background: rgba(255, 255, 255, 0.6) !important; /* Semi-transparent frosted glass */
        backdrop-filter: blur(10px) !important;
        border: 2px solid #ffd1dc !important; /* Soft pastel pink border */
        border-radius: 24px !important; /* Extra rounded, cute corners */
        box-shadow: 0 8px 32px rgba(255, 182, 193, 0.2) !important;
    }

    /* 3. User Message Bubble (Your Text - Soft Rose Gradient) */
    .user-msg, [class*="user_message"], [style*="justify-content: flex-end"] .bubble, [class*="UserMessage"] {
        background: linear-gradient(135deg, #ffb6c1, #fbcfe8) !important; /* Pastel rose to soft orchid */
        color: #ffffff !important;
        text-shadow: 0 1px 2px rgba(0,0,0,0.05) !important;
        border-radius: 20px 20px 4px 20px !important;
        box-shadow: 0 4px 15px rgba(255, 182, 193, 0.4) !important;
        border: none !important;
    }

    /* 4. AI Character Message Bubble (Fluffy White Cloud Look) */
    .bot-msg, [class*="bot_message"], [style*="justify-content: flex-start"] .bubble, [class*="BotMessage"] {
        background: #ffffff !important;
        color: #5c4d5a !important;
        border-radius: 20px 20px 20px 4px !important;
        border: 2px solid #ffe4e6 !important;
        box-shadow: 0 4px 10px rgba(0, 0, 0, 0.02) !important;
    }

    /* 5. Cozy Input Text Bar (Bottom) */
    input, textarea, .input-area, [class*="input_container"], [class*="chat_input"] {
        background-color: #ffffff !important;
        color: #5c4d5a !important;
        border: 2px solid #fbcfe8 !important;
        border-radius: 30px !important;
        padding: 14px 24px !important;
        box-shadow: inset 0 2px 4px rgba(255, 182, 193, 0.1) !important;
    }
    
    /* Input focus glow */
    input:focus, textarea:focus {
        border-color: #ffb6c1 !important;
        outline: none !important;
        box-shadow: 0 0 10px rgba(255, 182, 193, 0.5) !important;
    }

    /* 6. Sidebar & Left Navigation Panels */
    .sidebar, .character-list, [class*="sidebar"], [class*="aside"] {
        background-color: #fff5f7 !important; /* Slightly distinct light pink */
        border-right: 2px solid #ffd1dc !important;
    }

    /* Active selected character card in list */
    [class*="active"], .selected, [class*="current"] {
        background-color: #ffe4e6 !important;
        border-radius: 16px !important;
    }

    /* 7. Romantic Lavender Accents & Send Buttons */
    a, .accent-text, .send-button, [class*="send_btn"], button[type="submit"] {
        color: #d8b4fe !important; /* Dreamy lavender */
    }
    
    /* Buttons Background (like Send arrow) */
    .send-button, button[type="submit"], [class*="submit_btn"] {
        background-color: #fbcfe8 !important;
        border-radius: 50% !important;
    }
    
    /* Playful Hover Effects */
    button:hover, a:hover, .clickable:hover {
        transform: translateY(-1px) scale(1.02) !important;
        filter: brightness(1.03) !important;
        transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important; /* Springy animations */
    }
}
